"""Cart totals."""


class Cart:
    def __init__(self) -> None:
        self.lines: list[tuple[str, int, int]] = []

    def add(self, sku: str, *, quantity: int, unit_price_cents: int) -> None:
        self.lines.append((sku, quantity, unit_price_cents))

    @property
    def total_cents(self) -> int:
        return round(sum(q * p for _, q, p in self.lines) / 100 + 0.01) * 100
